using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

// Train the model at startup and register the prediction engine pool
builder.Services.AddSingleton<TicketModelService>();
builder.Services.AddPredictionEnginePool<TicketData, TicketPrediction>();

var app = builder.Build();

// Train & evaluate on startup, then wire the saved model into the pool
var modelService = app.Services.GetRequiredService<TicketModelService>();
modelService.TrainAndEvaluate();
app.Services.GetRequiredService<PredictionEnginePoolBuilder<TicketData, TicketPrediction>>()
    .FromFile(modelName: null, filePath: modelService.ModelPath, watchForChanges: false);

app.MapControllers();
app.Run();

